    const primeira = parseCompetencia(input.primeira_competencia || input.mes || input.competencia);
    if (!valorTotal || isNaN(valorTotal) || valorTotal <= 0) return 'Erro: informe o valor_total (numero maior que zero).';
    if (!parcelas || parcelas <= 0) return 'Erro: informe o numero de parcelas (inteiro maior que zero).';
    if (!primeira) return 'Erro: informe a primeira_competencia. Ex: {"acao":"parcelamento","descricao":"notebook","valor_total":3000,"parcelas":10,"cartao":"Nubank","primeira_competencia":"07/2026"}.';
    const parcela = Number((valorTotal / parcelas).toFixed(2));
    const out = await withTx(client, async (c) => {
      // idempotencia: nao relancar o MESMO parcelamento (mesmos campos) no mesmo dia
      const dup = await c.query("SELECT id FROM gastos_parcelados WHERE usuario=$1 AND descricao=$2 AND cartao=$3 AND valor_total=$4 AND parcelas=$5 AND primeira_competencia=$6 AND criado_em > NOW() - INTERVAL '1 day' LIMIT 1", [USUARIO, descricao, cartao, valorTotal, parcelas, primeira]);
      if (dup.rows.length) return { msg: '⚠️ Esse parcelamento ja foi lancado hoje (evitei duplicar): ' + descricao + ' ' + parcelas + 'x ' + cartao + '.' };
      const rec = await c.query('INSERT INTO gastos_parcelados(usuario,descricao,categoria,cartao,valor_total,parcelas,primeira_competencia) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id', [USUARIO, descricao, categoria, cartao, valorTotal, parcelas, primeira]);
      const linhas = [];
      for (let i = 0; i < parcelas; i++) {
        const comp = addMonths(primeira, i);
        const valor = i === parcelas - 1 ? Number((valorTotal - parcela * (parcelas - 1)).toFixed(2)) : parcela;
        await c.query("INSERT INTO faturas(usuario,cartao,competencia,valor,pago,pago_parcial,atualizado_em) VALUES($1,$2,$3,$4,false,0,NOW()) ON CONFLICT (usuario,cartao,competencia) DO UPDATE SET valor=faturas.valor+$4, atualizado_em=NOW()", [USUARIO, cartao, comp, valor]);
        linhas.push(compLabel(comp) + ': ' + brl(valor));
      }
      await audit(c, { usuario: USUARIO, acao: 'lancar_parcelamento', entidade: 'gastos_parcelados', entidade_id: String(rec.rows[0].id), depois: { descricao, categoria, cartao, valorTotal, parcelas, primeira } });
      return { msg: '✅ Parcelamento criado: ' + descricao + ' em ' + parcelas + 'x no ' + cartao + '.\n' + linhas.join('\n') };
    });
    return out.msg;
  }

  // ---------------- PAGAMENTO PARCIAL ----------------
  if (/parcial|pagamento/.test(acao)) {
    const comp = parseCompetencia(input.mes || input.competencia);
    const cartao = String(input.cartao || '').trim().toLowerCase();
    const valor = parseValor(input.valor_pago ?? input.valor);
    if (!comp) return 'Erro: informe o mes do pagamento. Ex: {"acao":"pagamento_parcial","mes":"junho","cartao":"Inter","valor_pago":500}.';
    if (!valor || isNaN(valor) || valor <= 0) return 'Erro: informe o valor_pago (numero maior que zero). Para quitar a fatura inteira use {"acao":"marcar","status":"paga"}.';
    const params = [USUARIO, comp]; let where = 'usuario=$1 AND competencia=$2';
    if (cartao) { params.push(cartao); where += ' AND lower(cartao)=lower($3)'; }
    const out = await withTx(client, async (c) => {
      const before = (await c.query('SELECT * FROM faturas WHERE ' + where + ' ORDER BY cartao', params)).rows;
      if (!before.length) return { msg: 'Nenhuma fatura encontrada para ' + compLabel(comp) + (cartao ? ' no cartao ' + cartao : '') + '.' };
      if (before.length > 1) return { msg: 'Erro: ha varias faturas em ' + compLabel(comp) + '. Informe o cartao. Ex: {"acao":"pagamento_parcial","mes":"' + compLabel(comp) + '","cartao":"Inter","valor_pago":500}.' };
      const idx = params.length + 1;
      await c.query('UPDATE faturas SET pago_parcial=LEAST(valor,COALESCE(pago_parcial,0)+$' + idx + '), pago=(COALESCE(pago_parcial,0)+$' + idx + ')>=valor, pago_em=CASE WHEN (COALESCE(pago_parcial,0)+$' + idx + ')>=valor THEN COALESCE(pago_em,NOW()) ELSE pago_em END, atualizado_em=NOW() WHERE ' + where, [...params, valor]);
      const after = (await c.query('SELECT cartao,valor,COALESCE(pago,false) pago,COALESCE(pago_parcial,0) pago_parcial FROM faturas WHERE ' + where + ' ORDER BY cartao', params)).rows;
      await audit(c, { usuario: USUARIO, acao: 'registrar_pagamento_fatura', entidade: 'faturas', entidade_id: comp, antes: before, depois: after });
      const linhas = after.map(x => '• ' + x.cartao + ': ' + brl(x.pago_parcial) + '/' + brl(x.valor) + ' - ' + (x.pago ? 'pago' : 'parcial/pendente')).join('\n');
      return { msg: '✅ Pagamento registrado para ' + compLabel(comp) + '.\n' + linhas };
    });
