    const vrq=await client.query("SELECT COALESCE(SUM(valor),0) t FROM gastos WHERE usuario='casa' AND origem IS DISTINCT FROM 'fixo' AND criado_em>=date_trunc('month',$1::date) AND criado_em<date_trunc('month',$2::date)",[comp,next]);
