    const fpq=await client.query("SELECT COALESCE(SUM((COALESCE(total_oficial,valor))-COALESCE(pago_parcial,0)) FILTER (WHERE NOT COALESCE(pago,false)),0) pendente, COALESCE(SUM(COALESCE(total_oficial,valor)),0) total FROM faturas WHERE usuario='casa' AND competencia=$1",[comp]);
    const fx=Number(fxq.rows[0].t||0), vr=Number(vrq.rows[0].t||0), aj=Number(ajq.rows[0].ajuste||0), ftot=Number(fpq.rows[0].total||0), fpend=Number(fpq.rows[0].pendente||0), vinc=Number(ajq.rows[0].vinc||0);
    const despesa=fx+vr+aj;
    return '📊 Previsão '+compLabel(comp)+'\n\n📅 Competência (despesa real):\n• Fixos: '+brl(fx)+'\n• Variáveis: '+brl(vr)+(aj>0?'\n• Ajuste de fatura: '+brl(aj):'')+'\n💵 Despesa do mês: '+brl(despesa)+'\n\n💳 Caixa (faturas — liquidação, não nova despesa):\n• Faturas do mês: '+brl(ftot)+'\n• A pagar: '+brl(fpend)+(vinc>0?'\n   ⓘ '+brl(vinc)+' já contam nas compras acima':'');
  }

  // ---------------- ALERTAS (read-only) ----------------
  if (/alert/.test(acao)) {
    const comp = parseCompetencia(input.mes || input.competencia); const prev = addMonths(comp, -1);
    const atual = await client.query("SELECT cartao,valor FROM faturas WHERE usuario=$1 AND competencia=$2", [USUARIO, comp]);
    const ant = await client.query("SELECT cartao,valor FROM faturas WHERE usuario=$1 AND competencia=$2", [USUARIO, prev]);
    const old = new Map(ant.rows.map(x => [normText(x.cartao), Number(x.valor || 0)]));
    const alerts = [];
    for (const x of atual.rows) { const b = old.get(normText(x.cartao)) || 0; const n = Number(x.valor || 0); if (b > 0) { const pct = Math.round((n - b) / b * 100); if (Math.abs(pct) >= 25) alerts.push('• ' + x.cartao + ': ' + (pct > 0 ? '+' : '') + pct + '% (' + brl(b) + ' → ' + brl(n) + ')'); } else if (n > 0) { alerts.push('• ' + x.cartao + ': novo valor ' + brl(n)); } }
