    msg += '\n\nFaturas: ' + brl(totalF) + ' | pendente: ' + brl(pend) + '\n';
    msg += faturas.rows.map(x => '• ' + x.cartao + ': ' + brl(x.valor) + ' - ' + (x.pago ? 'pago' : 'pendente')).join('\n') || '• nenhuma';
    return msg;
  }

